from collections import defaultdict

class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        k = len(set(nums))
        n = len(nums)
        cnt = defaultdict(int)
        distinct = 0
        r = 0
        ans = 0
        for l in range(n):
            while r < n and distinct < k:
                if cnt[nums[r]] == 0:
                    distinct += 1
                cnt[nums[r]] += 1
                r += 1
            if distinct == k:
                ans += n - r + 1
            cnt[nums[l]] -= 1
            if cnt[nums[l]] == 0:
                distinct -= 1
        return ans

