class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        req = {e: c for e, c in requirements}
        M = max(c for _, c in requirements)
        dp = [0] * (M + 1)
        dp[0] = 1
        if 0 in req:
            if req[0] != 0:
                return 0
        for i in range(1, n):
            pre = [0] * (M + 2)
            for c in range(M + 1):
                pre[c + 1] = (pre[c] + dp[c]) % MOD
            ndp = [0] * (M + 1)
            for c in range(M + 1):
                lo = max(0, c - i)
                ndp[c] = (pre[c + 1] - pre[lo]) % MOD
            if i in req:
                t = req[i]
                v = ndp[t]
                ndp = [0] * (M + 1)
                ndp[t] = v
            dp = ndp
        return dp[req[n - 1]] % MOD

