class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7
        req = {e: c for e, c in requirements}
        M = req[n - 1]
        dp = [0] * (M + 1)
        dp[0] = 1
        def apply(i, dp):
            if i in req:
                c = req[i]
                new = [0] * (M + 1)
                if c <= M:
                    new[c] = dp[c]
                return new
            return dp
        dp = apply(0, dp)
        for i in range(1, n):
            pre = [0] * (M + 2)
            for j in range(M + 1):
                pre[j + 1] = (pre[j] + dp[j]) % MOD
            nd = [0] * (M + 1)
            for j in range(M + 1):
                lo = max(0, j - i)
                nd[j] = (pre[j + 1] - pre[lo]) % MOD
            dp = apply(i, nd)
        return dp[M] % MOD

