class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        # position BIT
        pt = [0] * (n + 1)
        LOG = 1
        while (1 << LOG) <= n:
            LOG += 1
        total = [0]

        def padd(i, v):
            total[0] += v
            i += 1
            while i <= n:
                pt[i] += v
                i += i & -i

        def ppre(i):  # count of positions <= i
            i += 1
            s = 0
            while i > 0:
                s += pt[i]
                i -= i & -i
            return s

        def kth(k):  # 1-indexed k-th smallest position
            pos = 0
            for b in range(LOG, -1, -1):
                np_ = pos + (1 << b)
                if np_ <= n and pt[np_] < k:
                    pos = np_
                    k -= pt[np_]
            return pos  # 0-indexed position

        # length BITs
        cb = [0] * (n + 1)
        sb = [0] * (n + 1)
        tot = [0, 0]

        def ladd(L, v):
            tot[0] += v
            tot[1] += v * L
            i = L
            while i <= n:
                cb[i] += v
                sb[i] += v * L
                i += i & -i

        def lpre(i):
            c = s = 0
            while i > 0:
                c += cb[i]
                s += sb[i]
                i -= i & -i
            return c, s

        def rlen(a, b):
            d = (b - a) % n
            return d if d else n

        def pred(p):
            c = ppre(p - 1) if p > 0 else 0
            return kth(c) if c > 0 else kth(total[0])

        def succ(p):
            c = ppre(p)
            return kth(c + 1) if c < total[0] else kth(1)

        isb = [False] * n

        def add_break(p):
            if total[0] == 0:
                padd(p, 1)
                ladd(n, 1)
            else:
                a = pred(p)
                b = succ(p)
                ladd(rlen(a, b), -1)
                ladd(rlen(a, p), 1)
                ladd(rlen(p, b), 1)
                padd(p, 1)
            isb[p] = True

        def rem_break(p):
            padd(p, -1)
            if total[0] == 0:
                ladd(n, -1)
            else:
                a = pred(p)
                b = succ(p)
                ladd(rlen(a, p), -1)
                ladd(rlen(p, b), -1)
                ladd(rlen(a, b), 1)
            isb[p] = False

        for i in range(n):
            if colors[i] == colors[(i + 1) % n]:
                add_break(i)

        res = []
        for q in queries:
            if q[0] == 1:
                s = q[1]
                if total[0] == 0:
                    res.append(n)
                    continue
                c, sm = lpre(s - 1)
                cnt = tot[0] - c
                ssum = tot[1] - sm
                res.append(ssum - (s - 1) * cnt)
            else:
                idx, col = q[1], q[2]
                if colors[idx] == col:
                    continue
                ps = [(idx - 1) % n, idx]
                for p in ps:
                    if isb[p]:
                        rem_break(p)
                colors[idx] = col
                for p in ps:
                    if not isb[p] and colors[p] == colors[(p + 1) % n]:
                        add_break(p)
        return res

