class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        col = colors[:]
        # position BIT
        pt = [0] * (n + 1)
        LOG = 1
        while (1 << LOG) <= n:
            LOG += 1
        total = [0]

        def padd(i, v):
            i += 1
            while i <= n:
                pt[i] += v
                i += i & -i

        def pq(i):  # count of positions <= i
            i += 1
            s = 0
            while i > 0:
                s += pt[i]
                i -= i & -i
            return s

        def kth(k):  # 1-indexed k -> position (0-indexed)
            pos = 0
            for b in range(LOG, -1, -1):
                np = pos + (1 << b)
                if np <= n and pt[np] < k:
                    pos = np
                    k -= pt[np]
            return pos  # pos is 1-indexed index minus 1 => 0-indexed

        cnt = [0] * (n + 2)
        sm = [0] * (n + 2)

        def ladd(L, v):
            i = L
            w = v * L
            while i <= n:
                cnt[i] += v
                sm[i] += w
                i += i & -i

        def lq(i):
            c = s = 0
            while i > 0:
                c += cnt[i]
                s += sm[i]
                i -= i & -i
            return c, s

        def d(a, b):
            if a == b:
                return n
            return (b - a) % n

        bad = [False] * n

        def neighbors(p):
            # p not in set, set non-empty
            c = pq(p - 1) if p > 0 else 0
            a = kth(c) if c > 0 else kth(total[0])
            c2 = pq(p)
            b = kth(c2 + 1) if c2 < total[0] else kth(1)
            return a, b

        def add(p):
            if total[0] == 0:
                ladd(n, 1)
            else:
                a, b = neighbors(p)
                ladd(d(a, b), -1)
                ladd(d(a, p), 1)
                ladd(d(p, b), 1)
            padd(p, 1)
            total[0] += 1
            bad[p] = True

        def remove(p):
            padd(p, -1)
            total[0] -= 1
            bad[p] = False
            if total[0] == 0:
                ladd(n, -1)
            else:
                a, b = neighbors(p)
                ladd(d(a, p), -1)
                ladd(d(p, b), -1)
                ladd(d(a, b), 1)

        for i in range(n):
            if col[i] == col[(i + 1) % n]:
                add(i)

        res = []
        for q in queries:
            if q[0] == 1:
                k = q[1]
                if total[0] == 0:
                    res.append(n)
                else:
                    ca, sa = lq(n)
                    cb, sb = lq(k - 1)
                    c = ca - cb
                    s = sa - sb
                    res.append(s - (k - 1) * c)
            else:
                i, c = q[1], q[2]
                if col[i] == c:
                    continue
                es = [(i - 1) % n, i]
                for e in es:
                    if bad[e]:
                        remove(e)
                col[i] = c
                for e in es:
                    if col[e] == col[(e + 1) % n]:
                        add(e)
        return res

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [0] * n
        p = 1 % k
        for i in range(n):
            pw[i] = p
            p = p * 10 % k
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pw[i])
            else:
                w.append((pw[i] + pw[j]) % k)
        full = (1 << k) - 1
        reach = [0] * (h + 1)
        reach[h] = 1
        for i in range(h - 1, -1, -1):
            m = reach[i + 1]
            nm = 0
            lo = 1 if i == 0 else 0
            for d in range(lo, 10):
                c = d * w[i] % k
                if c == 0:
                    nm |= m
                else:
                    nm |= ((m << c) | (m >> (k - c))) & full
            reach[i] = nm
        res = []
        rem = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                c = d * w[i] % k
                need = (-rem - c) % k
                if (reach[i + 1] >> need) & 1:
                    res.append(str(d))
                    rem = (rem + c) % k
                    break
        first = ''.join(res)
        if n % 2 == 1:
            return first + first[:-1][::-1]
        return first + first[::-1]

