class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        total = sum(fruits[i][i] for i in range(n))
        NEG = float('-inf')

        def solve(get):
            dp = [NEG] * (n + 1)
            dp[n - 1] = get(0, n - 1)
            for i in range(1, n - 1):
                new = [NEG] * (n + 1)
                lo = max(i + 1, n - 1 - i)
                for j in range(lo, n):
                    best = dp[j]
                    if dp[j - 1] > best:
                        best = dp[j - 1]
                    if dp[j + 1] > best:
                        best = dp[j + 1]
                    if best != NEG:
                        new[j] = best + get(i, j)
                dp = new
            return dp[n - 1]

        total += solve(lambda i, j: fruits[i][j])
        total += solve(lambda i, j: fruits[j][i])
        return total

