class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        D = 300  # diffs 0..299
        dp = [None] * 301
        seen = []
        ans = 1
        for x in nums:
            cur = [1] * D
            for v in seen:
                d = x - v
                if d < 0:
                    d = -d
                val = dp[v][d] + 1
                if val > cur[d]:
                    cur[d] = val
            # suffix max
            cur = list(accumulate(reversed(cur), max))
            cur.reverse()
            if dp[x] is None:
                dp[x] = cur
                seen.append(x)
            else:
                dp[x] = list(map(max, dp[x], cur))
            if dp[x][0] > ans:
                ans = dp[x][0]
        return ans

