import sys
from functools import lru_cache

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); K = int(data[1]); S = data[2]
    counts = [0]*26
    for ch in S:
        counts[ord(ch)-97] += 1
    memo = {}

    def canon(counts, window):
        ids = {}
        pat = []
        for c in window:
            if c not in ids:
                ids[c] = len(ids)
            pat.append(ids[c])
        order = sorted(ids, key=lambda c: ids[c])
        wc = tuple(counts[c] for c in order)
        others = tuple(sorted(counts[c] for c in range(26) if c not in ids and counts[c] > 0))
        return (tuple(pat), wc, others)

    sys.setrecursionlimit(10000)

    def f(window, remaining):
        if remaining == 0:
            return 1
        key = canon(counts, window)
        if key in memo:
            return memo[key]
        total = 0
        for c in range(26):
            if counts[c] > 0:
                new = window + (c,)
                if len(new) >= K:
                    seg = new[-K:]
                    if seg == seg[::-1]:
                        continue
                counts[c] -= 1
                nw = new[-(K-1):] if K - 1 > 0 else ()
                total += f(nw, remaining - 1)
                counts[c] += 1
        memo[key] = total
        return total

    print(f((), N))

