import sys, heapq
def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); m=int(data[1])
    A=[0]*m;B=[0]*m;C=[0]*m
    adj=[[] for _ in range(n+1)]
    p=2
    for i in range(m):
        a=int(data[p]);b=int(data[p+1]);c=int(data[p+2]);p+=3
        A[i]=a;B[i]=b;C[i]=c
        adj[a].append((b,c));adj[b].append((a,c))
    INF=float('inf')
    def dij(s):
        d=[INF]*(n+1);d[s]=0
        h=[(0,s)]
        while h:
            du,u=heapq.heappop(h)
            if du>d[u]: continue
            for v,c in adj[u]:
                nd=du+c
                if nd<d[v]:
                    d[v]=nd;heapq.heappush(h,(nd,v))
        return d
    d1=dij(1);dn=dij(n)
    D=d1[n]
    iv=[None]*m
    pts=set()
    for i in range(m):
        a=A[i];b=B[i];c=C[i]
        if d1[a]+c+dn[b]==D:
            iv[i]=(d1[a],d1[b])
        elif d1[b]+c+dn[a]==D:
            iv[i]=(d1[b],d1[a])
        if iv[i] is not None:
            pts.add(iv[i][0]);pts.add(iv[i][1])
    xs=sorted(pts)
    idx={x:k for k,x in enumerate(xs)}
    K=len(xs)
    diff=[0]*(K+1)
    for i in range(m):
        if iv[i] is not None:
            l=idx[iv[i][0]];r=idx[iv[i][1]]
