    cov=[0]*(K+1)
    s=0
    for k in range(K):
        s+=diff[k];cov[k]=s
    out=[]
    for i in range(m):
        if iv[i] is None:
            out.append("No");continue
        l=idx[iv[i][0]];r=idx[iv[i][1]]
        if r==l+1 and cov[l]==1:
            out.append("Yes")
        else:
            out.append("No")
    sys.stdout.write("\n".join(out)+"\n")
