def get_total_number_of_sequences(m, n):
    if n <= 0 or m <= 0:
        return 0
    # dp[j] = number of sequences of current length ending with value j
    dp = [0] + [1] * m  # length 1: any value 1..m
    for _ in range(n - 1):
        # prefix sums of previous dp
        prefix = [0] * (m + 1)
        for j in range(1, m + 1):
            prefix[j] = prefix[j - 1] + dp[j]
        new_dp = [0] * (m + 1)
        for j in range(1, m + 1):
            new_dp[j] = prefix[j // 2]
        dp = new_dp
    return sum(dp)


if __name__ == "__main__":
