def dict_filter(d, n):
    """
    Return a new dictionary containing only the entries of `d`
    whose values are greater than or equal to `n`.

    Args:
        d (dict): The input dictionary.
        n (int | float): The threshold value.

    Returns:
        dict: A filtered dictionary with entries where value >= n.
    """
    return {key: value for key, value in d.items() if value >= n}


if __name__ == "__main__":
    # Provided test
    assert dict_filter(
        {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Kierra Gentry': 165, 'Pierre Cox': 190},
        170
    ) == {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Pierre Cox': 190}

    # Additional tests
    assert dict_filter(
        {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Kierra Gentry': 165, 'Pierre Cox': 190},
        180
    ) == {'Alden Cantrell': 180, 'Pierre Cox': 190}

    assert dict_filter(
        {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Kierra Gentry': 165, 'Pierre Cox': 190},
        190
    ) == {'Pierre Cox': 190}

    assert dict_filter({}, 10) == {}
    assert dict_filter({'a': 1, 'b': 2}, 5) == {}
    assert dict_filter({'a': 5, 'b': 10}, 0) == {'a': 5, 'b': 10}

    print("All tests passed!")
