def _kadane(arr):
    best = cur = arr[0]
    for x in arr[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best


def max_sub_array_sum_repeated(a, n, k):
    a = list(a[:n])
    if n == 0 or k <= 0:
        return 0
    if k == 1:
        return _kadane(a)
    best = _kadane(a + a)
    total = sum(a)
    if total > 0:
        best += (k - 2) * total
    return best


