    assert dict_depth({'a': 1, 'b': {'c': 'python'}}) == 2
    assert dict_depth({1: 'Sun', 2: {3: {4: 'Mon'}}}) == 3
    assert dict_depth({}) == 1
    print("All tests passed.")

