def max_sum_increasing_subseq(a, n, index, k):
    """
    Return the maximum sum of an increasing subsequence chosen from the
    prefix a[0..index] that also includes the element a[k], where k > index.
    """
    if not (0 <= index < k < n):
        raise ValueError("Require 0 <= index < k < n")

    # dp[i][j]: max sum of increasing subsequence using elements from
    # a[0..i] and then ending with a[j] (j > i).
    dp = [[0] * n for _ in range(n)]

    # Base case: prefix consisting of only a[0]
    for j in range(n):
        if a[j] > a[0]:
            dp[0][j] = a[0] + a[j]
        else:
            dp[0][j] = a[j]

    # Fill the table
    for i in range(1, n):
        for j in range(n):
            if j > i and a[j] > a[i]:
                # Either include a[i] (best sum ending at a[i] using prefix
                # before i, i.e. dp[i-1][i]) followed by a[j], or skip a[i].
                dp[i][j] = max(dp[i - 1][i] + a[j], dp[i - 1][j])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[index][k]


