def set_left_most_unset_bit(n):
    # If all bits are already set (e.g. 1, 3, 7, 15...), return n unchanged
    if not (n & (n + 1)):
        return n

    pos = 0
    count = 0
    temp = n
    # Track the position of the highest unset bit within n's bit length
    while temp:
        if not (temp & 1):
            pos = count
        count += 1
        temp >>= 1

    return n | (1 << pos)


