def check_distinct(test_tup):
    """
    Return True if the tuple contains no duplicate elements, False otherwise.
    Works for hashable elements efficiently; falls back to O(n^2) comparison
    for unhashable elements.
    """
    try:
        return len(set(test_tup)) == len(test_tup)
    except TypeError:
        # Fallback for unhashable elements (e.g., lists inside the tuple)
        seen = []
        for item in test_tup:
            if item in seen:
                return False
            seen.append(item)
        return True


