def sum_of_digits(nums):
    """
    Compute the sum of all digits of each number in the given list.
    Handles nested lists, negative numbers, and ignores non-digit characters.
    """
    def flatten(items):
        for item in items:
            if isinstance(item, (list, tuple)):
                yield from flatten(item)
            else:
