def multiple_to_single(L):
    """Join a list of integers into a single integer by concatenating their digits."""
    if not L:
        raise ValueError("Input list must not be empty")
    # Handle a possible leading negative sign on the first number
    sign = -1 if L[0] < 0 else 1
    joined = "".join(str(abs(x)) for x in L)
    return sign * int(joined)


