def sumofFactors(n):
    """Return the sum of all even factors of n."""
    if n <= 0 or n % 2 != 0:
        return 0  # odd numbers (and non-positive input) have no even factors

    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i % 2 == 0:
                total += i
            if j != i and j % 2 == 0:
                total += j
        i += 1
    return total


assert sumofFactors(18) == 26  # 2 + 6 + 18
assert sumofFactors(30) == 48  # 2 + 6 + 10 + 30
assert sumofFactors(6) == 8    # 2 + 6
assert sumofFactors(7) == 0

if __name__ == "__main__":
    print(sumofFactors(18))  # 26

