def max_product(arr):
    if not arr:
        return 0
    best = arr[0]
    current = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            current *= arr[i]
        else:
            current = arr[i]
        best = max(best, current)
    return best


