def find_dissimilar(test_tup1, test_tup2):
    """
    Return a tuple of elements that appear in exactly one of the two tuples
    (symmetric difference), preserving the order of first appearance:
    first the unique elements of test_tup1, then those of test_tup2.
    """
    set1, set2 = set(test_tup1), set(test_tup2)
    result = []
    seen = set()

    for item in test_tup1:
        if item not in set2 and item not in seen:
            result.append(item)
            seen.add(item)

    for item in test_tup2:
        if item not in set1 and item not in seen:
            result.append(item)
            seen.add(item)

    return tuple(result)


