def perfect_squares(a, b):
    if a > b:
        a, b = b, a
    if b < 0:
        return []
    start = max(a, 0)
    root = math.isqrt(start)
    if root * root < start:
        root += 1
    result = []
    while root * root <= b:
        result.append(root * root)
        root += 1
    return result

