def largest_subset(a):
    """
    Return the size of the largest subset of `a` such that for every pair
    (x, y) in the subset, either x % y == 0 or y % x == 0.
    """
    if not a:
        return 0

    nums = sorted(a)
    n = len(nums)
    dp = [1] * n  # dp[i]: largest divisible subset ending with nums[i]

    for i in range(n):
        for j in range(i):
            # nums[j] <= nums[i]; check divisibility (handle zero safely)
            if nums[j] != 0 and nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)
            elif nums[j] == 0 and nums[i] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)


if __name__ == "__main__":
    assert largest_subset([1, 3, 6, 13, 17, 18]) == 4
    assert largest_subset([10, 5, 3, 15, 20]) == 3
    assert largest_subset([18, 1, 3, 6, 13, 17]) == 4
    assert largest_subset([]) == 0
    assert largest_subset([7]) == 1
    print("All tests passed!")

def largest_subset(a):
    """
    Return the size of the largest subset of `a` such that for every pair
    (x, y) in the subset, either x % y == 0 or y % x == 0.
    """
    if not a:
        return 0

    nums = sorted(a)
    n = len(nums)
    dp = [1] * n  # dp[i]: size of largest divisible chain ending at nums[i]

    for i in range(1, n):
        for j in range(i):
            # Guard against division by zero: 0 cannot divide anything
            # (except 0 itself in the "divisible" sense x % y requires y != 0).
            if nums[j] != 0 and nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)
            elif nums[j] == 0 and nums[i] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)


if __name__ == "__main__":
    assert largest_subset([1, 3, 6, 13, 17, 18]) == 4
    assert largest_subset([10, 5, 3, 15, 20]) == 3
    assert largest_subset([18, 1, 3, 6, 13, 17]) == 4
    assert largest_subset([]) == 0
    assert largest_subset([7]) == 1
    print("All tests passed!")

response_text:
Sort the numbers so that each element only needs to be checked against smaller ones. Let `dp[i]` be the size of the largest divisible subset that ends at `a[i]`. Then `dp[i]` is 1 plus the largest `dp[j]` (for `j < i`) where `a[i]` is divisible by `a[j]`, or just 1 if there is no such `j`. This works because divisibility is transitive in a sorted chain: if `a[j]` divides `a[i]`, everything in `a[j]`'s chain also divides `a[i]`.

For the example, the subset `[1, 3, 6, 18]` gives the answer 4.

