def largest_subset(a):
    if not a:
        return 0
    a = sorted(a)
    n = len(a)
    dp = [1] * n
    for i in range(n - 2, -1, -1):
        best = 0
        for j in range(i + 1, n):
            if a[i] != 0 and a[j] % a[i] == 0:
                best = max(best, dp[j])
        dp[i] = 1 + best
    return max(dp)


