def get_coordinates(test_tup):
    """
    Return all coordinates adjacent to the given coordinate tuple,
    including the coordinate itself, as a list of [x, y] lists
    in row-major order.
    """
    def adjac(ele, sub=[]):
        if not ele:
            yield sub
        else:
            for j in range(ele[0] - 1, ele[0] + 2):
                yield from adjac(ele[1:], sub + [j])

    return list(adjac(test_tup))


