    """
    Merge three dictionaries into one.
    When a key appears in more than one dictionary, the value from the
    earliest dictionary (dict1, then dict2, then dict3) takes precedence,
    matching the semantics of collections.ChainMap.
    """
    merged = {}
    # Update in reverse order so earlier dictionaries override later ones
    for d in (dict3, dict2, dict1):
        merged.update(d)
    return merged


