def power(a, b):
    """Calculate a raised to the power b using exponentiation by squaring."""
    if b == 0:
        return 1
    if b < 0:
        return 1 / power(a, -b)

    result = 1
    base = a
    exp = b
    while exp > 0:
        if exp % 2 == 1:
            result *= base
        base *= base
        exp //= 2
    return result


if __name__ == "__main__":
    assert power(3, 4) == 81
    assert power(2, 3) == 8
    assert power(5, 5) == 3125
    assert power(7, 0) == 1
    assert power(2, -2) == 0.25
    print("All tests passed!")

