import math


def multiply_num(numbers):
    """Multiply all numbers in the sequence and divide by its length."""
    numbers = list(numbers)
    if not numbers:
        raise ValueError("Cannot compute for an empty sequence.")
    total = 1
    for x in numbers:
        total *= x
    return total / len(numbers)


assert math.isclose(multiply_num((8, 2, 3, -1, 7)), -67.2, rel_tol=0.001)
assert math.isclose(multiply_num((-10, -20, -30)), -2000.0, rel_tol=0.001)
assert math.isclose(multiply_num((19, 15, 18)), 1710.0, rel_tol=0.001)

if __name__ == "__main__":
    print(multiply_num((8, 2, 3, -1, 7)))  # -67.2

